// index.js
import React from 'react';
import ReactDOM from 'react-dom';
// 1) install these:
//    npm install carbon-components carbon-components-react @carbon/icons-react
// 2) import the CSS from carbon-components
import 'carbon-components/css/carbon-components.min.css';
import { Search } from 'carbon-components-react';

function App() {
  return (
    <div style={{ padding: '2rem' }}>
      <Search
        id="search-autofill"
        labelText="Search"
        placeHolderText="Type to see autofill"
        // give it a name so Chrome will remember your entry
        name="search-autofill"
        // remove `light` so we see the default white background
      />
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));

// Steps to run:
// 1) yarn start or npm start (create-react-app environment)
// 2) In Chrome, type something into the search field and press Enter.
//    Chrome will remember that entry for next time.
// 3) Refresh the page, click in the search field again and accept the autofill suggestion (you’ll see the sky-blue background).  
// 4) Notice the clear (×) button on the right: it’s sitting on the raw sky-blue, making the white icon very low contrast.
